import { Router, type RequestHandler } from "express";
import { z } from "zod";
import { asyncHandler } from "../../common/async-handler.js";
import { HttpError } from "../../common/http-error.js";
import { requireAuth, requireRoles } from "../auth/auth.middleware.js";
import { recordAuditEvent } from "../audit/audit.service.js";
import { assessVendor, createVendor, getVendorOverview, listVendors, updateVendor } from "./vendor.service.js";
import { assessVendorSchema, createVendorSchema, listVendorsSchema, updateVendorSchema } from "./vendor.validation.js";
export const vendorRouter = Router();
vendorRouter.use(requireAuth);
const validate = (schema: z.ZodTypeAny, source: "body" | "query" = "body"): RequestHandler => (req, res, next) => { const parsed = schema.safeParse(req[source]); if (!parsed.success) return next(new HttpError(400, "Request validation failed.", "VALIDATION_ERROR")); if (source === "body") req.body = parsed.data; else res.locals.validatedQuery = parsed.data; next(); };
const idParam = (req: Parameters<RequestHandler>[0]) => { const id = req.params.vendorId; if (typeof id !== "string" || !/^[a-f\d]{24}$/i.test(id)) throw new HttpError(400, "Invalid vendor identifier.", "INVALID_ID"); return id; };
const audit = (req: Parameters<RequestHandler>[0], action: string, vendorId: string, summary: string) => recordAuditEvent({ tenantId: req.auth!.tenantId, actorId: req.auth!.userId, action, resourceType: "VENDOR", resourceId: vendorId, summary, ...(req.header("x-request-id") ? { requestId: req.header("x-request-id")! } : {}) });
vendorRouter.post("/", requireRoles("OWNER", "ADMIN"), validate(createVendorSchema), asyncHandler(async (req, res) => { const vendor = await createVendor(req.auth!.tenantId, req.auth!.userId, req.body); await audit(req, "VENDOR_CREATED", vendor.id, `Created vendor profile: ${vendor.legalName}`); res.status(201).json({ success: true, data: { vendor } }); }));
vendorRouter.get("/", validate(listVendorsSchema, "query"), asyncHandler(async (req, res) => { const result = await listVendors(req.auth!.tenantId, res.locals.validatedQuery); res.json({ success: true, data: result }); }));
vendorRouter.get("/:vendorId/overview", asyncHandler(async (req, res) => { const overview = await getVendorOverview(req.auth!.tenantId, idParam(req)); res.json({ success: true, data: { overview } }); }));
vendorRouter.patch("/:vendorId", requireRoles("OWNER", "ADMIN"), validate(updateVendorSchema), asyncHandler(async (req, res) => { const vendor = await updateVendor(req.auth!.tenantId, req.auth!.userId, idParam(req), req.body); if (!vendor) throw new HttpError(404, "Vendor not found.", "VENDOR_NOT_FOUND"); await audit(req, "VENDOR_UPDATED", vendor.id, `Updated vendor profile: ${vendor.legalName}`); res.json({ success: true, data: { vendor } }); }));
vendorRouter.post("/:vendorId/assessments", requireRoles("OWNER", "ADMIN"), validate(assessVendorSchema), asyncHandler(async (req, res) => { const vendor = await assessVendor(req.auth!.tenantId, req.auth!.userId, idParam(req), req.body); if (!vendor) throw new HttpError(404, "Vendor not found.", "VENDOR_NOT_FOUND"); await audit(req, "VENDOR_RISK_ASSESSED", vendor.id, `Recorded vendor risk assessment: ${vendor.legalName}`); res.status(201).json({ success: true, data: { vendor } }); }));
